<script setup lang="ts">
import { useI18n } from 'vue-i18n'
import type { Settings } from '../types'
import Card from './Card.vue'
const { t } = useI18n()
const { settings, showAgentToken, agentCommand, username, randomToken, copyAgentToken, saveSettings, copyAgentCommand, logout, uiGateUrl, randomUiGatePath, copyUiGateLink } = defineProps<{ settings: Settings, showAgentToken: boolean, agentCommand: string, username: string, randomToken: () => void, copyAgentToken: () => void, saveSettings: () => void, copyAgentCommand: () => void, logout: () => void, uiGateUrl: string, randomUiGatePath: () => void, copyUiGateLink: () => void }>()
const emit = defineEmits<{ (event: 'toggle-agent-token'): void; (event: 'show-password'): void }>()
</script>
<template>
<div class="section-head"><div><h2>{{t("系统设置")}}</h2><p>{{t("管理服务器接入方式和管理员账户。")}}</p></div></div><div class="settings-grid"><Card as="section" class="panel setting-card"><h3>{{t("服务器接入")}}</h3><p>{{t("监控服务使用此密钥连接 Avenlytic。更换密钥后，已添加的服务器需要更新密钥并重启监控服务。")}}</p><label>{{t("服务器接入密钥")}}</label><div class="inline"><input v-model="settings.agent_token" :type="showAgentToken?'text':'password'" :placeholder="t('生成密钥后复制并妥善保存；保存后无法再次查看')"><button class="ghost" @click="emit('toggle-agent-token')">{{showAgentToken?t("隐藏"):t("显示")}}</button><button class="ghost" @click="randomToken">{{t("生成新密钥")}}</button><button class="ghost" @click="copyAgentToken">{{t("复制密钥")}}</button></div><small>{{t("当前状态：")}}{{settings.agent_token_configured?t("已准备就绪"):t("尚未配置")}}</small><label>{{t("离线告警等待时间（秒）")}}</label><input v-model.number="settings.offline_after_seconds" type="number" min="15" max="3600"><div class="gate-toggle"><input id="ui-gate-enabled" v-model="settings.ui_gate_enabled" type="checkbox" @change="settings.ui_gate_enabled || (settings.ui_gate_path = '')"><label for="ui-gate-enabled">{{t("启用 UI 安全链接")}}</label></div><p class="hint">{{t("启用后，访问管理页面和 API 前必须先通过安全链接；Agent 上报和健康检查不受影响。")}}</p><label>{{t("安全链接路径")}}</label><div class="inline"><input v-model="settings.ui_gate_path" type="text" minlength="3" maxlength="128" :placeholder="settings.ui_gate_enabled?t('已配置的安全链接不会回显；输入新值可更换'):t('至少 3 位，仅支持字母、数字、连字符和下划线')"><button class="ghost" @click="randomUiGatePath">{{t("随机生成")}}</button></div><div v-if="uiGateUrl" class="inline"><input :value="uiGateUrl" readonly><button class="ghost" @click="copyUiGateLink">{{t("复制安全链接")}}</button></div><p v-if="uiGateUrl" class="hint">{{t("完整入口链接显示在上方，可复制分享；当前不会自动发送邮件。请在关闭页面前保存好链接。短路径容易被猜，建议使用随机生成。")}}</p><button class="primary" @click="saveSettings">{{t("保存系统设置")}}</button></Card><Card as="section" class="panel setting-card"><h3>{{t("添加 Linux 服务器")}}</h3><p>{{t("请在需要监控的 Linux 服务器上按以下步骤操作。")}}</p><pre>{{agentCommand}}</pre><button class="ghost" @click="copyAgentCommand">{{t("复制接入命令")}}</button><p class="hint">{{t("Agent 上报频率说明")}}</p><button class="ghost" @click="emit('show-password')">{{t("修改管理员密码")}}</button></Card><Card as="section" class="panel setting-card"><h3>{{t("管理员账户")}}</h3><p>{{t("当前登录用户：")}}<b>{{username}}</b></p><button class="ghost" @click="emit('show-password')">{{t("修改密码")}}</button><button class="ghost" @click="logout">{{t("退出登录")}}</button></Card><Card as="section" class="panel setting-card"><h3>{{t("数据保存位置")}}</h3><div class="info-row"><span>{{t("数据存储")}}</span><b>{{t("数据保存在本服务所在服务器的本地文件中")}}</b></div></Card></div>
